import json,urllib.parse,urllib.request,time
Q=['title:(manuscripts) AND title:(Rutland) AND title:(Belvoir)','title:(Hastings) AND title:(manuscripts) AND title:(Huntingdon)','title:(Lonsdale) AND title:(manuscripts)','title:(Cowper) AND title:(manuscripts) AND title:(Panshanger)','title:(Hamilton) AND title:(manuscripts) AND title:(Supplementary)','title:(Ormonde) AND title:(manuscripts)','title:(Ormonde) AND title:(calendar)','title:(Nicholas) AND title:(papers) AND title:(Camden)','title:(Hardwicke) AND title:(state papers)','title:(Royal Society) AND title:(historical records)','title:(Thomas Birch) AND title:(history of the Royal Society)','title:(Border papers) AND title:(calendar)','title:(Rawdon) AND title:(papers)','title:(Carte) AND title:(letters) AND title:(Ormonde)','title:(Stuart papers) AND title:(Windsor)','title:(Clarendon) AND title:(state papers) AND title:(Ormonde)','title:(report) AND title:(manuscripts) AND title:(Historical Manuscripts Commission) AND title:(Rutland)','title:(Cecil) AND title:(Salisbury) AND title:(Hatfield)','title:(Sir Joseph Williamson letters) AND title:(Camden)','title:(Nicholas) AND title:(Edward) AND title:(papers)','title:(Notes) AND title:(Ormonde) AND title:(Carte)','title:(Report) AND title:(Mss) AND title:(Hamilton) AND title:(Duke of)','title:(Report on the manuscripts of) AND title:(Lord Middleton)','title:(Report on the manuscripts of) AND title:(Earl of Dartmouth)','title:(Report on the manuscripts of) AND title:(Earl Bathurst)','title:(manuscripts of the Marquess of Bath)','title:(manuscripts of Lord Kenyon)','title:(manuscripts of the Marquis of Ormonde)','title:(Ormonde Papers) AND title:(Kilkenny)','title:(Calendar of Ormond) AND title:(Carte)','title:(Report) AND title:(Hodgson) AND title:(manuscripts)','title:(Report) AND title:(manuscripts) AND title:(Fortescue) AND title:(Dropmore)','title:(manuscripts of Sir Henry Hinde)','title:(Report) AND title:(manuscripts) AND title:(Mss of the Earl of Eglinton)','title:(Report) AND title:(manuscripts) AND title:(Ormonde) AND title:(Montague)']
out={}
for q in Q:
    u="https://archive.org/advancedsearch.php?q=%s&fl[]=identifier&fl[]=title&fl[]=date&fl[]=imagecount&rows=50&output=json"%urllib.parse.quote(q+' AND mediatype:texts')
    try:
        d=json.load(urllib.request.urlopen(urllib.request.Request(u,headers={"User-Agent":"Mozilla/5.0"}),timeout=60))
        for x in d["response"]["docs"]: out[x["identifier"]]={"title":x.get("title"),"date":x.get("date"),"n":x.get("imagecount"),"q":q}
        print(q[:60],len(d["response"]["docs"]),flush=True)
    except Exception as e: print("fail",q,e,flush=True)
    time.sleep(1.2)
json.dump(out,open("ids2.json","w"),indent=0)
